    /// <summary>按类型取预设图形。目录给文件夹形，其它兜底 <c>doc</c>。</summary>
    public static Geometry ForPath(string path, bool isDir)
    {
        if (isDir) return Folder;
        string ext = Path.GetExtension(path ?? string.Empty).ToLowerInvariant();
        if (ext.Length == 0) return Fallback;

        foreach (var (name, exts) in Map)
            if (Array.IndexOf(exts, ext) >= 0) return ByName[name];

        return Fallback;
    }

    /// <summary>
    /// 程序 / 快捷方式：**保留真 Shell 图标**——VS Code / 微信 / Steam 这类图标的辨识度
    /// 就是内容本身，换成统一图形反而丢信息（2026-09-24 用户拍板的替代范围）。
    /// </summary>
    public static bool IsProgram(string path)
    {
        string ext = Path.GetExtension(path ?? string.Empty).ToLowerInvariant();
        return ext.Length > 0 && Array.IndexOf(PROGRAMS, ext) >= 0;
    }

    private static readonly string[] PROGRAMS = { ".exe", ".lnk", ".msi", ".bat", ".cmd", ".ps1", ".appref" };

