        /// <summary>按 key 取图形。key 为空或不认识（老数据被改坏）时返回 null，调用方落回 2x2。</summary>
        public static Geometry? Find(string? key) =>
            !string.IsNullOrEmpty(key) && ByKey.TryGetValue(key, out var g) ? g : null;

        /// <summary>按 key 取中文名。认不出来就把 key 原样返回（宁可显示得丑，也别显示空白）。</summary>
        public static string Label(string? key) =>
            !string.IsNullOrEmpty(key) && Labels.TryGetValue(key, out var s) ? s : key ?? string.Empty;
